import{_t as e,it as t,n,rt as r}from"./chunks/framework.C6TizvAB.js";import{G as i,H as a,U as o,V as s,W as c}from"./chunks/assets.DAjhvrpn.js";var l=JSON.parse(`{"title":"Configure behavior & recording systems","description":"","frontmatter":{"title":"Configure behavior & recording systems","lang":"en-US"},"headers":[],"relativePath":"software/configure_systems.md","filePath":"software/configure_systems.md"}`),u={name:`software/configure_systems.md`};function d(n,l,u,d,f,p){return e(),r(`div`,null,[...l[0]||=[t(`<h1 id="configure-behavior-recording-systems" tabindex="-1">Configure behavior &amp; recording systems <a class="header-anchor" href="#configure-behavior-recording-systems" aria-label="Permalink to “Configure behavior &amp; recording systems”">​</a></h1><h2 id="configure-new-behavior-rig-system" tabindex="-1">Configure a new behavior rig <a class="header-anchor" href="#configure-new-behavior-rig-system" aria-label="Permalink to “Configure a new behavior rig”">​</a></h2><h3 id="first-steps" tabindex="-1">First steps <a class="header-anchor" href="#first-steps" aria-label="Permalink to “First steps”">​</a></h3><h4 id="mount-cup-pni-drives" tabindex="-1">Mount the PNI cup drives <a class="header-anchor" href="#mount-cup-pni-drives" aria-label="Permalink to “Mount the PNI cup drives”">​</a></h4><ol><li>From Windows Explorer, select &quot;Map Network Drive&quot; and enter:</li></ol><ul><li><code>\\\\cup.pni.princeton.edu\\braininit\\</code> (for braininit)</li><li><code>\\\\cup.pni.princeton.edu\\u19_dj\\</code> (for u19_dj)</li></ul><ol start="2"><li>Authenticate with your NetID and PU password (NOT your PNI password, which may be different). When prompted for your username, enter <code>PRINCETON\\netid</code> (PRINCETON can be upper or lower case), where <code>netid</code> is your PU NetID.</li></ol><h4 id="install-matlab-2020a-or-higher" tabindex="-1">Install MATLAB R2020a or later <a class="header-anchor" href="#install-matlab-2020a-or-higher" aria-label="Permalink to “Install MATLAB R2020a or later”">​</a></h4><h4 id="download-and-install-nidaqmx-from-national-instruments-website" tabindex="-1">Download and install NI-DAQmx from the <a href="https://ni.com/r/downloaddaqmx">National Instruments website</a> <a class="header-anchor" href="#download-and-install-nidaqmx-from-national-instruments-website" aria-label="Permalink to “Download and install NI-DAQmx from the National Instruments website”">​</a></h4><h4 id="download-and-install-microsoft-visual-studio-community" tabindex="-1">Download and install Microsoft Visual Studio Community <a class="header-anchor" href="#download-and-install-microsoft-visual-studio-community" aria-label="Permalink to “Download and install Microsoft Visual Studio Community”">​</a></h4><ol><li>Select a version compatible with the installed MATLAB version. This typically means a Visual Studio release year earlier than the MATLAB release year (e.g., VS Community 2022 for MATLAB R2024a).</li><li>Make sure to install the &quot;Desktop development with C++&quot; workload.</li></ol><h4 id="install-git-for-windows" tabindex="-1">Install Git for Windows <a class="header-anchor" href="#install-git-for-windows" aria-label="Permalink to “Install Git for Windows”">​</a></h4><ol><li>Install it from this <a href="https://git-for-windows.github.io/">link</a>.</li></ol><h5 id="installation-options" tabindex="-1">Installation options <a class="header-anchor" href="#installation-options" aria-label="Permalink to “Installation options”">​</a></h5><ul><li>Use Git from the Windows Command Prompt (5th pane)</li><li>Checkout as-is, commit as-is (6th pane)</li></ul><h4 id="create-ssh-key-to-clone-repositories" tabindex="-1">Create an SSH key to clone repositories <a class="header-anchor" href="#create-ssh-key-to-clone-repositories" aria-label="Permalink to “Create an SSH key to clone repositories”">​</a></h4><ol><li>Open Git Bash.</li><li><code>ssh-keygen -t ed25519 -C &quot;vrrigsbi@princeton.edu&quot;</code></li><li>Leave the passphrase empty (press Enter twice).</li><li><code>eval &quot;$(ssh-agent -s)&quot;</code></li><li><code>ssh-add ~/.ssh/id_ed25519</code></li></ol><h4 id="add-key-to-virmen-user-in-github" tabindex="-1">Add the key to the vrrigs user on GitHub <a class="header-anchor" href="#add-key-to-virmen-user-in-github" aria-label="Permalink to “Add the key to the vrrigs user on GitHub”">​</a></h4><ol><li>Copy the ssh public key to the clipboard in Git Bash: <code>clip &lt; ~/.ssh/id_ed25519.pub</code></li><li>Open <a href="https://github.com/login" target="_blank" rel="noreferrer">GitHub</a>.</li><li>Log in as the vrrigs user (ask your lab manager for the password).</li></ol><figure><img src="`+i+`" alt="Vrrigs GitHub login" width="662" height="730" loading="lazy"><figcaption>Vrrigs GitHub login</figcaption></figure><ol start="4"><li>Go to Settings -&gt; SSH and GPG keys.</li></ol><figure><img src="`+c+`" alt="Vrrigs ssh keys section" width="638" height="924" loading="lazy"><figcaption>Vrrigs ssh keys section</figcaption></figure><ol start="5"><li>Click the <code>New SSH key</code> button.</li><li>Add a meaningful title for the key and paste the public key from the clipboard into the &quot;Key&quot; text area.</li><li>Click the <code>Add SSH key</code> button.</li></ol><h4 id="compiler" tabindex="-1">Compiler <a class="header-anchor" href="#compiler" aria-label="Permalink to “Compiler”">​</a></h4><ol><li>Install the Visual Studio C++ compiler from <a href="https://visualstudio.microsoft.com/downloads/">https://visualstudio.microsoft.com/downloads/</a>, making sure to select C++ support.</li><li>In MATLAB, run <code>mex -setup -v</code>. This sets up the compiler. It should output something like &quot;Microsoft Visual C++ 202X&quot;.</li></ol><h3 id="u19-pipeline-matlab-repository" tabindex="-1">U19-pipeline-matlab repository <a class="header-anchor" href="#u19-pipeline-matlab-repository" aria-label="Permalink to “U19-pipeline-matlab repository”">​</a></h3><ol><li>Open Git Bash and execute: <code>cd /c/Experiments</code></li><li>Clone the <strong>U19-pipeline-matlab</strong> repository: <code>git clone git@github.com:BrainCOGS/U19-pipeline-matlab.git</code></li></ol><h4 id="matlab-instructions" tabindex="-1">MATLAB instructions <a class="header-anchor" href="#matlab-instructions" aria-label="Permalink to “MATLAB instructions”">​</a></h4><ol start="3"><li>Run <code>dj_initial_conf(0)</code>.</li><li>Enter the DB user name and password.</li></ol><h3 id="virmen-repository" tabindex="-1">ViRMEn repository <a class="header-anchor" href="#virmen-repository" aria-label="Permalink to “ViRMEn repository”">​</a></h3><ol><li>Create the <code>C:\\Experiments</code> directory</li><li>Open Git Bash and execute: <code>cd /c/Experiments</code>.</li><li>Execute <code>git config --global user.email &quot;vrrigsbi@princeton.edu&quot;</code>.</li><li>Clone the <strong>ViRMEn</strong> repository: <code>git clone git@github.com:BrainCOGS/ViRMEn.git</code>.</li></ol><h4 id="matlab-instructions-1" tabindex="-1">MATLAB instructions <a class="header-anchor" href="#matlab-instructions-1" aria-label="Permalink to “MATLAB instructions”">​</a></h4><ol start="5"><li>Open MATLAB as Administrator.</li><li>Run <code>install_virmen</code> inside <code>C:\\Experiments\\ViRMEn</code>.</li></ol><ul><li>If compilation fails, run <code>mex -setup c++</code> to select the <strong>Visual Studio C++ compiler</strong>.</li></ul><ol start="7"><li>Run:</li></ol><ul><li><code>import_scheduled_tasks(1)</code> if this is a rig in room 165 (or one mainly managed by techs)</li><li><code>import_scheduled_tasks(0)</code> if this is an acquisition (ephys/imaging) rig or a rig managed by researchers</li></ul><ol start="8"><li>Open the file <code>C:\\Experiments\\ViRMEn\\RigParameters.m</code> and edit the corresponding variables:</li></ol><ul><li><strong>rig:</strong> (RigName in the format: <code>Room#-&quot;Rig&quot;#-T</code>)</li><li><strong>rig_type:</strong> (<code>miniVR</code> or <code>NormalVR</code>)</li><li><strong>NI-DAQ channels</strong>, in the corresponding variables (ask your lab manager about these parameters)</li><li><strong>Mini VR projection parameters</strong> (ask your lab manager about these parameters)</li></ul><ol start="9"><li>Run <code>lab.utils.add_behavior_rig(RigParameters.rig)</code>.</li><li>Run the <code>live_calibration</code> experiment (ask your lab manager about this process).</li><li>Create a MATLAB shortcut and set <strong>Start in</strong> to <code>C:\\Experiments\\ViRMEn</code>.</li><li>Pin this shortcut to the Windows taskbar.</li></ol><figure><img src="`+o+`" alt="MATLAB Shortcut example" width="878" height="1208" loading="lazy"><figcaption>MATLAB Shortcut example</figcaption></figure><h3 id="matlab-add-ons" tabindex="-1">MATLAB add-ons <a class="header-anchor" href="#matlab-add-ons" aria-label="Permalink to “MATLAB add-ons”">​</a></h3><p>If not all toolboxes were installed with MATLAB, make sure these add-ons are installed:</p><ul><li>Image Acquisition Toolbox</li><li>Image Processing Toolbox</li><li>Image Acquisition Toolbox Support Package for GenICam Interface</li><li>Image Acquisition Toolbox Support Package for OS Generic Video Interface</li><li>PsychToolbox</li><li>Statistics and Machine Learning Toolbox</li><li>Instrument Control Toolbox</li><li>Data Acquisition Toolbox</li><li>Zaber</li></ul><h2 id="modify-the-sleep-behaviors" tabindex="-1">Change the sleep settings <a class="header-anchor" href="#modify-the-sleep-behaviors" aria-label="Permalink to “Change the sleep settings”">​</a></h2><p>To keep the screen from turning off while subjects are training:</p><ol><li>In Windows <a href="https://support.microsoft.com/en-us/windows/how-to-adjust-power-and-sleep-settings-in-windows-26f623b5-4fcc-4194-863d-b824e5ea7679">Power &amp; Sleep settings</a>, set &quot;Turn my screen off after&quot; to the longest option.</li><li>Also set &quot;Make my device sleep after&quot; to the longest option.</li></ol><h2 id="configure-new-recording-system" tabindex="-1">Configure a new recording system <a class="header-anchor" href="#configure-new-recording-system" aria-label="Permalink to “Configure a new recording system”">​</a></h2><ul><li>First, install everything necessary for the appropriate recording modality (SpikeGLX for electrophysiology, ScanImage for imaging).</li></ul><ol><li>From Windows Explorer, select &quot;Map Network Drive&quot; and enter:</li></ol><ul><li><code>\\\\cup.pni.princeton.edu\\braininit\\</code> (for braininit)</li><li><code>\\\\cup.pni.princeton.edu\\u19_dj\\</code> (for u19_dj)</li></ul><ol start="2"><li>Authenticate with your NetID and PU password (NOT your PNI password, which may be different). When prompted for your username, enter <code>PRINCETON\\netid</code> (PRINCETON can be upper or lower case), where <code>netid</code> is your PU NetID.</li><li>Copy the Automation GUI files: copy <code>\\\\cup.pni.princeton.edu\\braininit\\Shared\\AutomationGUI_Installation\\AutomationGUI_update</code> to the Desktop.</li><li>Run <code>Desktop\\AutomationGUI_update\\firstTimeAutomationGUI.BAT</code>.</li></ol><ul><li>Install Git Bash and Anaconda from it.</li></ul><figure><img src="`+a+`" alt="Anaconda advanced options step" width="992" height="780" loading="lazy"><figcaption>Anaconda advanced options step</figcaption></figure><ul><li>On the Anaconda advanced options step, check the <strong>&quot;Add Anaconda3 to my PATH environment variable&quot;</strong> checkbox.</li></ul><ol start="5"><li>Run <code>Desktop\\AutomationGUI_update\\update_AutomationGUI.BAT</code>.</li><li>Follow the instructions to install the Recording Automation GUI (also called the Workflow Console GUI).</li></ol><figure><img src="`+s+`" alt="Recording Automation GUI installer" width="1380" height="826" loading="lazy"><figcaption>Recording Automation GUI installer</figcaption></figure><h3 id="register-recording-system" tabindex="-1">Register recording system <a class="header-anchor" href="#register-recording-system" aria-label="Permalink to “Register recording system”">​</a></h3><p>On a computer with access to the database (e.g., any rig computer):</p><ol><li>Open MATLAB.</li><li>Execute: <code>lab.utils.add_recording_system((recording_system_name), (modality))</code> where:</li></ol><ul><li><strong>recording_system_name:</strong> (in the format: <code>Room#-Recording</code>).</li><li><strong>modality:</strong> (one of the following: <code>electrophysiology, 2photon, 3photon, mesoscope</code>).</li></ul>`,60)]])}var f=n(u,[[`render`,d]]);export{l as __pageData,f as default};